const data = {
  shift_summary: "Shift window: 2026-11-21 00:00 to 08:00 UTC. Evelyn Brooks handed off to Daniel Rivera.",
  open_items: [{
    ticket: "IDN-221",
    service: "Account Recovery Service",
    status: "Recovery emails are arriving late for some users.",
    severity: "SEV3",
    owner: "Daniel Rivera",
    next_action: "Check email delivery times at 08:15 UTC."
  }],
  watch_list: ["Watch Account Recovery Service for recovery email delays above five minutes."],
  recently_resolved: ["IDN-219, Account Sign-In Service: The sign-in error alert cleared at 05:42 UTC."],
  open_questions: []
};
const schema = load("schema");
function check(value, rule, path) {
  if (rule.$ref) return check(value, rule.$ref.slice(2).split("/").reduce((node, key) => node[key], schema), path);
  const type = Array.isArray(value) ? "array" : value === null ? "null" : typeof value;
  if (type !== rule.type) throw Error(`${path}: expected ${rule.type}`);
  if (type === "object") {
    for (const key of rule.required ?? []) if (!Object.hasOwn(value, key)) throw Error(`${path}: missing ${key}`);
    for (const [key, entry] of Object.entries(value)) {
      if (rule.properties[key]) check(entry, rule.properties[key], `${path}.${key}`);
      else if (rule.additionalProperties === false) throw Error(`${path}: unexpected ${key}`);
    }
  }
  if (type === "array") value.forEach((item, i) => check(item, rule.items, `${path}[${i}]`));
  if (rule.minLength && [...value].length < rule.minLength) throw Error(`${path}: too short`);
  if (rule.enum && !rule.enum.includes(value)) throw Error(`${path}: invalid enum value`);
}
const output = JSON.stringify(data, null, 2);
check(JSON.parse(output), schema, "$");
text(output);

